css:
.bauxia-sim-container {
    padding: 28px;
    background: linear-gradient(160deg, #1f2933 0%, #2a3441 60%, #2d3a3f 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #f0e9dd;
    box-sizing: border-box;
}

.bauxia-sim-container *,
.bauxia-sim-container *::before,
.bauxia-sim-container *::after {
    box-sizing: border-box;
}

.bauxia-sim-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 24px;
    padding: 28px 32px;
    margin-bottom: 24px;
    background: linear-gradient(120deg, rgba(217,160,100,0.18) 0%, rgba(201,123,60,0.08) 100%);
    border-left: 5px solid #c97b3c;
    border-radius: 6px;
    box-shadow: 0 6px 20px rgba(0,0,0,0.25);
}

.bauxia-sim-header-content { flex: 1; }

.bauxia-sim-header-eyebrow {
    color: #d9a064;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    margin-bottom: 10px;
}

.bauxia-sim-header h1 {
    color: #f7eed7;
    font-size: 1.7rem;
    font-weight: 700;
    line-height: 1.2;
    margin: 0 0 8px 0;
    letter-spacing: 0.01em;
}

.bauxia-sim-subtitle {
    color: #c8bfaf;
    font-size: 0.95rem;
    margin: 0;
    font-style: italic;
}

.bauxia-sim-period-badge {
    background: rgba(15,22,28,0.6);
    border: 1px solid rgba(217,160,100,0.35);
    border-radius: 8px;
    padding: 14px 22px;
    text-align: center;
    min-width: 130px;
}

.bauxia-sim-period-badge-label {
    display: block;
    color: #d9a064;
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin-bottom: 4px;
}

.bauxia-sim-period-badge-value {
    color: #f7eed7;
    font-size: 1.6rem;
    font-weight: 700;
}

.bauxia-sim-period-of {
    font-size: 0.9rem;
    color: #c8bfaf;
    font-weight: 400;
    margin: 0 4px;
}

.bauxia-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.bauxia-sim-kpi-card {
    background: linear-gradient(145deg, #2d3a48 0%, #34414f 100%);
    border: 1px solid rgba(217,160,100,0.18);
    border-radius: 8px;
    padding: 20px 22px;
    position: relative;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.bauxia-sim-kpi-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(0,0,0,0.3);
}

.bauxia-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, #c97b3c 0%, #d9a064 100%);
    border-radius: 8px 8px 0 0;
}

.bauxia-sim-kpi-primary {
    background: linear-gradient(145deg, #3a4a3f 0%, #2f3d4a 100%);
    border-color: rgba(156,175,136,0.4);
}

.bauxia-sim-kpi-primary::before {
    background: linear-gradient(90deg, #9caf88 0%, #d9a064 100%);
}

.bauxia-sim-kpi-label {
    color: #c8bfaf;
    font-size: 0.72rem;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    margin-bottom: 10px;
    line-height: 1.3;
}

.bauxia-sim-kpi-value {
    color: #f7eed7;
    font-size: 1.85rem;
    font-weight: 700;
    line-height: 1;
}

.bauxia-sim-kpi-primary .bauxia-sim-kpi-value {
    color: #d9e6c2;
}

.bauxia-sim-kpi-meta {
    margin-top: 8px;
    color: #d9a064;
    font-size: 0.78rem;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}

.bauxia-sim-briefing {
    background: rgba(15,22,28,0.45);
    border: 1px solid rgba(217,160,100,0.22);
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 24px;
    border-left: 4px solid #d9a064;
}

.bauxia-sim-briefing-heading {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 12px;
    flex-wrap: wrap;
}

.bauxia-sim-briefing-tag {
    background: #c97b3c;
    color: #1d2730;
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    padding: 4px 10px;
    border-radius: 3px;
}

.bauxia-sim-briefing-round {
    color: #f7eed7;
    font-weight: 600;
    font-size: 1.05rem;
}

.bauxia-sim-briefing-text {
    color: #e6dec8;
    font-size: 0.96rem;
    line-height: 1.55;
}

.bauxia-sim-controls {
    background: linear-gradient(155deg, #2d3a48 0%, #303d4b 100%);
    border: 1px solid rgba(217,160,100,0.2);
    border-radius: 8px;
    padding: 26px 28px;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.18);
}

.bauxia-sim-controls-heading {
    color: #d9a064;
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin: 0 0 18px 0;
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(217,160,100,0.2);
}

.bauxia-sim-decision-list {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 18px;
}

.bauxia-sim-decision {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.bauxia-sim-decision label {
    color: #f7eed7;
    font-weight: 600;
    font-size: 0.88rem;
    margin: 0;
}

.bauxia-sim-controls select,
.bauxia-sim-controls input[type="number"],
.bauxia-sim-controls input[type="text"] {
    background: #1a232b;
    border: 1px solid rgba(217,160,100,0.35);
    color: #f0e9dd;
    border-radius: 5px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.92rem;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    appearance: none;
    -webkit-appearance: none;
    background-image: linear-gradient(45deg, transparent 50%, #d9a064 50%), linear-gradient(135deg, #d9a064 50%, transparent 50%);
    background-position: calc(100% - 18px) 50%, calc(100% - 12px) 50%;
    background-size: 6px 6px, 6px 6px;
    background-repeat: no-repeat;
    padding-right: 32px;
}

.bauxia-sim-controls select:focus,
.bauxia-sim-controls input:focus {
    outline: none;
    border-color: #d9a064;
    box-shadow: 0 0 0 3px rgba(217,160,100,0.18);
}

.bauxia-sim-controls select option {
    background: #1a232b;
    color: #f0e9dd;
    padding: 8px;
}

.bauxia-sim-actions {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-top: 22px;
    flex-wrap: wrap;
}

.bauxia-sim-submit.btn {
    background: linear-gradient(135deg, #c97b3c 0%, #d9a064 100%);
    border: none;
    color: #1f2933;
    font-weight: 700;
    letter-spacing: 0.04em;
    padding: 11px 26px;
    border-radius: 5px;
    transition: transform 0.15s ease, box-shadow 0.2s ease;
}

.bauxia-sim-submit.btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(201,123,60,0.4);
    color: #1f2933;
}

.bauxia-sim-undo.btn {
    background: transparent;
    border: 1px solid rgba(240,233,221,0.3);
    color: #c8bfaf;
    padding: 10px 18px;
    border-radius: 5px;
}

.bauxia-sim-undo.btn:hover {
    background: rgba(240,233,221,0.06);
    color: #f0e9dd;
}

.bauxia-sim-results-panel {
    background: rgba(15,22,28,0.45);
    border: 1px solid rgba(156,175,136,0.25);
    border-left: 4px solid #9caf88;
    border-radius: 8px;
    padding: 20px 26px;
    margin-bottom: 24px;
}

.bauxia-sim-results-heading {
    color: #9caf88;
    font-size: 0.78rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin-bottom: 10px;
}

.bauxia-sim-results-body {
    color: #e6dec8;
    font-size: 0.94rem;
    line-height: 1.6;
}

.bauxia-sim-history-panel {
    background: rgba(15,22,28,0.4);
    border: 1px solid rgba(240,233,221,0.1);
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 24px;
    overflow-x: auto;
}

.bauxia-sim-history-heading {
    color: #d9a064;
    font-size: 0.78rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin-bottom: 14px;
}

.bauxia-sim-history-table.table {
    color: #f0e9dd;
    margin: 0;
    font-size: 0.88rem;
    background: transparent;
}

.bauxia-sim-history-table.table thead th {
    color: #d9a064;
    font-weight: 700;
    font-size: 0.75rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    border-bottom: 1px solid rgba(217,160,100,0.3);
    border-top: none;
    padding: 10px 8px;
    background: transparent;
}

.bauxia-sim-history-table.table tbody td {
    color: #e6dec8;
    border-top: 1px solid rgba(240,233,221,0.06);
    padding: 10px 8px;
    background: transparent;
}

.bauxia-sim-history-table.table-striped tbody tr:nth-of-type(odd) {
    background: rgba(240,233,221,0.025);
}

.bauxia-sim-chart-panel {
    background: rgba(15,22,28,0.45);
    border: 1px solid rgba(240,233,221,0.1);
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 24px;
    height: 360px;
    position: relative;
}

.bauxia-sim-chart-panel canvas { max-height: 320px; }

@media (max-width: 768px) {
    .bauxia-sim-container { padding: 16px; }
    .bauxia-sim-header { flex-direction: column; padding: 20px 22px; }
    .bauxia-sim-header h1 { font-size: 1.35rem; }
    .bauxia-sim-period-badge { width: 100%; }
    .bauxia-sim-kpi-grid { grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); }
    .bauxia-sim-kpi-value { font-size: 1.4rem; }
    .bauxia-sim-decision-list { grid-template-columns: 1fr; }
    .bauxia-sim-actions { flex-direction: column; align-items: stretch; }
    .bauxia-sim-chart-panel { height: 300px; }
}

.bauxia-sim-container select:focus-visible,
.bauxia-sim-container button:focus-visible,
.bauxia-sim-container a:focus-visible {
    outline: 3px solid #1f2933;
    outline-offset: 2px;
}

.bauxia-sim-completion {
    background: #ffffff;
    border: 1px solid #d9dde3;
    border-left: 4px solid #c97b3c;
    border-radius: 4px;
    padding: 20px 24px;
    margin-bottom: 24px;
}

.bauxia-sim-completion-title {
    font-size: 1.1rem;
    font-weight: 600;
    margin: 0 0 10px 0;
}

.bauxia-sim-completion-insights li {
    margin-bottom: 8px;
    line-height: 1.5;
}

@media (prefers-reduced-motion: reduce) {
    .bauxia-sim-container *,
    .bauxia-sim-container *::before,
    .bauxia-sim-container *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

