            state.domainState.socialLicense = Math.max(0, Math.min(100, state.domainState.socialLicense + slDelta));
            state.domainState.communityTrust = Math.max(0, Math.min(100, state.domainState.communityTrust + ctDelta));
            state.domainState.boardConfidence = Math.max(0, Math.min(100, state.domainState.boardConfidence + bcDelta));
            state.domainState.covenantHeadroom = Math.max(-30, Math.min(60, state.domainState.covenantHeadroom + covDelta));
            state.domainState.cashImpact += cashDelta;

            state.domainState.socialLicenseHistory.push(state.domainState.socialLicense);
            state.domainState.communityTrustHistory.push(state.domainState.communityTrust);
            state.domainState.boardConfidenceHistory.push(state.domainState.boardConfidence);
            state.domainState.covenantHistory.push(state.domainState.covenantHeadroom);

            var ladder = window.mySimulation.t('ladder_withdrawal');
            if (state.domainState.socialLicense >= 75) ladder = window.mySimulation.t('ladder_co');
            else if (state.domainState.socialLicense >= 55) ladder = window.mySimulation.t('ladder_approval');
            else if (state.domainState.socialLicense >= 35) ladder = window.mySimulation.t('ladder_acceptance');

            if (!commentary) commentary = window.mySimulation.t('commentary_default') + '<br>';

            var composite = this._composite(state.domainState);
            state.domainState.overallScore = composite;
            state.domainState.totalScore = composite;
            state.domainState.score = composite;
            // platform score: composite is already the 0-100 metric getPerformanceSummary reports as the final verdict, so reuse it directly, clamped
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(composite))) });

            var self = this;
            var nextRound = round + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextRound });
            }, 500);

            return {
                period: state.currentPeriod,
                socialLicense: state.domainState.socialLicense,
                communityTrust: state.domainState.communityTrust,
                boardConfidence: state.domainState.boardConfidence,
                covenantHeadroom: state.domainState.covenantHeadroom,
                cashImpact: state.domainState.cashImpact,
                ladder: ladder,
                overallScore: composite,
                totalScore: composite,
                commentary: commentary
            };
        }

