        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var sl = ds.socialLicenseHistory || [];
            var labels = sl.map(function(_, i) { return i === 0 ? 'P0' : 'P' + i; });
            return {
                trajectoryChart: {
                    labels: labels,
                    datasets: [
                        { data: sl },
                        { data: ds.communityTrustHistory || [] },
                        { data: ds.boardConfidenceHistory || [] }
                    ]
