        _composite(ds) {
            if (!ds) return 0;
            var sl = ds.socialLicense || 0, ct = ds.communityTrust || 0, bc = ds.boardConfidence || 0;
            var score = Math.round(sl * 0.45 + ct * 0.35 + bc * 0.20);
            if ((ds.covenantHeadroom || 0) < 0) score = Math.min(score, 45);
            if (sl < 25) score = Math.min(score, 30);
            return Math.max(0, Math.min(100, score));
        }

        _band(sl, ct, bc, cov) {
            if (sl >= 70 && ct >= 65 && bc >= 70 && cov > 0) return 'coownership';
            if (sl >= 50 && ct >= 45 && cov > 0) return 'acceptance';
            if (sl >= 35) return 'fragile';
            return 'withdrawal';
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var t = window.mySimulation.t.bind(window.mySimulation);
            var lastResult = history[history.length - 1].results || {};
            var sl = lastResult.socialLicense || 0;
            var ct = lastResult.communityTrust || 0;
            var bc = lastResult.boardConfidence || 0;
            var cash = lastResult.cashImpact || 0;
            var cov = lastResult.covenantHeadroom || 0;

            var band = this._band(sl, ct, bc, cov);
            var composite = this._composite({
                socialLicense: sl, communityTrust: ct, boardConfidence: bc, covenantHeadroom: cov
            });

            var insights = [t('sum_' + band)];
            if (cov < 0) insights.push(t('sum_cov_breach'));
            if (cash < -7) insights.push(t('sum_cash_high'));
            if (cash > -1.5) insights.push(t('sum_cash_low'));
            insights.push(t('sum_patterns'));

            return {
                socialLicenseFinal: sl,
                communityTrustFinal: ct,
                boardConfidenceFinal: bc,
                cashImpact: cash,
                covenantHeadroom: cov,
                avgScore: composite,
                overallScore: composite,
                totalScore: composite,
                composite: composite,
                score: composite,
                performance: t('band_' + band),
                performanceKey: band,
                performanceLabel: t('band_' + band),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var s = summary || {};
            var band = s.performanceKey || s.performance || 'withdrawal';
            var html = '<div class="bauxia-sim-completion">';
            html += '<h3 class="bauxia-sim-completion-title">' + t('completion_title') + '</h3>';
            html += '<p class="bauxia-sim-completion-score"><strong>' + t('completion_score_label') + '</strong> ' +
                    (s.overallScore || 0) + ' / 100 &mdash; ' + (s.performanceLabel || t('band_' + band)) + '</p>';
            html += '<p>' + t('completion_kpis')
                        .replace('{sl}', Math.round(s.socialLicenseFinal || 0))
                        .replace('{ct}', Math.round(s.communityTrustFinal || 0))
                        .replace('{bc}', Math.round(s.boardConfidenceFinal || 0))
                        .replace('{cov}', Math.round(s.covenantHeadroom || 0))
                        .replace('{cash}', (s.cashImpact || 0).toFixed(2)) + '</p>';
            var ins = s.insights || [];
            if (ins.length) {
                html += '<ul class="bauxia-sim-completion-insights">';
                for (var i = 0; i < ins.length; i++) html += '<li>' + ins[i] + '</li>';
