        _updateBriefing(state) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var period = (state && state.currentPeriod) || 1;
            var titleEl = document.getElementById('roundTitle');
            var briefEl = document.getElementById('briefingText');
            var decContainer = document.getElementById('decisionList');

            if (period > this.ROUNDS.length) {
                if (titleEl) titleEl.textContent = t('finished_title');
                if (briefEl) briefEl.innerHTML = t('finished_text');
                if (decContainer) decContainer.innerHTML = '';
                var row = document.querySelector('.bauxia-sim-actions');
                if (row) row.style.display = 'none';
                var sb = document.getElementById('nextPeriodBtn');
                if (sb) { sb.disabled = true; sb.setAttribute('aria-disabled', 'true'); }
                return;
            }

            // before the first week is played the view placeholders show in the active language
            var fwState = window.mySimulation ? window.mySimulation.state : null;
            if (!(fwState && fwState.history && fwState.history.length)) {
                var ladderEl = document.getElementById('ladderDisplay');
                if (ladderEl) ladderEl.textContent = t('ladder_withdrawal');
                var commentEl = document.getElementById('commentaryDisplay');
                if (commentEl) commentEl.textContent = t('commentary_waiting');
            }

            var round = this.ROUNDS[period - 1];
            if (titleEl) titleEl.textContent = t(round.titleKey);
            if (briefEl) briefEl.innerHTML = t(round.summaryKey);

            if (decContainer) {
                var html = '';
                for (var i = 0; i < round.decisions.length; i++) {
                    var dec = round.decisions[i];
                    html += '<div class="bauxia-sim-decision">';
                    html += '<label for="input_' + dec.id + '">' + t(dec.labelKey) + '</label>';
                    html += '<select id="input_' + dec.id + '" class="bauxia-sim-select">';
                    html += '<option value="">' + t('choose_option') + '</option>';
                    for (var j = 0; j < dec.options.length; j++) {
                        var opt = dec.options[j];
                        html += '<option value="' + this._optCode(period, dec.id, opt.v) + '">' + t(opt.tKey) + '</option>';
                    }
                    html += '</select>';
                    html += '</div>';
                }
                decContainer.innerHTML = html;
                this._syncControlsFromDecisions(state);
            }
        }

        _syncControlsFromDecisions(state) {
            var d = state && state.decisions;
            if (!d) return;
            for (var k in d) {
                if (!Object.prototype.hasOwnProperty.call(d, k)) continue;
                var el = document.getElementById('input_' + k);
                if (el && d[k] !== null && d[k] !== undefined) el.value = this._optCode((state && state.currentPeriod) || 1, k, d[k]);
            }
        }

